			if ($subject == 'server') $done = true;

			if (isset($_REQUEST['report']) && !$done) {
				$vars .= 'report='.urlencode($_REQUEST['report']).'&';
				$trail['report'] = array(
					'title' => $lang['strreport'],
					'text'  => $_REQUEST['report'],
					'url'   => "reports.php?subject=report&{$vars}",
