					'url'   => "redirect.php?subject=database&{$vars}",
					'help'  => 'pg.database',
					'icon'  => 'Database'
				);
			} elseif (isset($_REQUEST['rolename']) && !$done) {
				$vars .= "subject=role&action=properties&rolename=".urlencode($_REQUEST['rolename']);
				$trail['role'] = array(
					'title' => $lang['strrole'],
