			'htm'=>'text/html', 
			'txt'=>'text/plain', 
			'css'=>'text/css', 
			'gif'=>'image/gif',
			'png'=>'image/x-png',
			'jpeg'=>'image/jpeg',
			'jpg'=>'image/jpeg',
			'JPG'=>'image/jpeg',
			'jpe'=>'image/jpeg',
