					}, 100);
					</script>
					<!-- End Stats Collector -->
STATSCOLLECTOR;
			}

			// Reset Cache Here
			$cache->set(Kohana::config('settings.subdomain').'_piwiktag', $tag, array('piwiktag'), 86400); // 1 Day
		}

		return $tag;

	}

