          "Rep" => $sentence_data[Entity\TSentence::$tok_rep],
          "Highlights" => array(),
          "Children" => array()
        );
      }
    }

  }


  $response = array(
    'data' => $data,
    'pageTitle' => htmlspecialchars($pageTitle, ENT_QUOTES)
  );

  echo json_encode($response);
