public function addFile($filename, $conditional_ie = false)
{
    $hash = md5($filename);
    if (!empty($this->_files[$hash])) {
        return;
    }

    $has_onload = $this->_eventBlacklist($filename);
    $this->_files[$hash] = array(
        'has_onload' => $has_onload,
        'filename' => $filename,
        'conditional_ie' => $conditional_ie
    );
}

