	$today = date('Y-m-d', time());
	$permanent = $options['popup_permanent'];
	$start_date = $options['start_date'];
	$end_date = $options['end_date'];
	$diff_start = strtotime($today) - strtotime($start_date);
	$diff_end = strtotime($end_date) - strtotime($today);
