    // this.
    if (/*overload*/mb_substr($pma_absolute_uri, 0, 7) != 'http://'
        && /*overload*/mb_substr($pma_absolute_uri, 0, 8) != 'https://'
    ) {
        $pma_absolute_uri
            = ($is_https ? 'https' : 'http')
            . ':'
            . (
                /*overload*/mb_substr($pma_absolute_uri, 0, 2) == '//'
                ? ''
                : '//'
            )
            . $pma_absolute_uri;
    }
}

