                $fee_data['setup_fee'] = $row['value'];
                $fee_value = bcadd($fee_value, $row['value'], $system->SETTINGS['moneydecimals']);
            } else {
                $tmp = bcdiv($row['value'], '100', $system->SETTINGS['moneydecimals']);
