		manager_del($name);
		$rights = manager_format_in($_REQUEST);
		manager_add($name,$secret,$deny,$permit,$rights['read'],$rights['write'],$writetimeout);
		needreload();
		break;
	case "conflict":
		//do nothing we are conflicting with the FreePBX Asterisk Manager User
		break;
	}
}

