				{
					$layout->navigate_notification(t(55, 'Item removed successfully.'), false);
					$out = functions_list();
				}
				else
				{
					$layout->navigate_notification(t(56, 'Unexpected error.'), false);
					$out = functions_form($item);
				}
			}
			break;

        case 'list':
		case 0: // list / search result
		default:			
			$out = functions_list();
			break;
	}

	return $out;
}

