                        $columns = 0;
                        $rows++;
                    }
                }else{
                    $result .= $v;
                    $columns++; // 1
                    if($columns>=$max_columns){
                        $columns = 0;
                        $rows++;
                    }
                }
            }
            if( (empty($atts['display'])) || (!empty($atts['display']) && $atts['display']!='slider') ){
                $result .= '</div>';
