                        $tmpdata,
                        [
                            'html'      => true,
                            'searchopt' => $so,
                            'raw_data'  => $data
                        ]
                    );
                }
            }
            if (!empty($specific)) {
                $out .= $specific;
            } else {
                if (
                    isset($so['toadd'])
                    && isset($so['toadd'][$data[$ID][$k]['name']])
                ) {
                    $out .= $so['toadd'][$data[$ID][$k]['name']];
                } else {
