    public function wrapAll($wrapper)
    {
        if (!$this->length()) {
            return $this;
        }

        return phpQuery::pq($wrapper, $this->getDocumentID())
                        ->clone()
                        ->insertBefore($this->get(0))
                        ->map(array($this, '___wrapAllCallback'))
                        ->append($this);
    }

