     * Enter description here...
     *
     * @param string|phpQueryObject
     *
     * @return phpQueryObject|QueryTemplatesSource|QueryTemplatesParse|QueryTemplatesSourceQuery
     */
    public function add($selector = null)
    {
        if (!$selector) {
            return $this;
        }
        $stack = array();
        $this->elementsBackup = $this->elements;
        $found = phpQuery::pq($selector, $this->getDocumentID());
        $this->merge($found->elements);

        return $this->newInstance();
    }

    /**
     */
    protected function merge()
    {
        foreach (func_get_args() as $nodes) {
            foreach ($nodes as $newNode) {
                if (!$this->elementsContainsNode($newNode)) {
                    $this->elements[] = $newNode;
                }
            }
        }
    }

    /**
     */
    protected function elementsContainsNode($nodeToCheck, $elementsStack = null)
    {
        $loop = !is_null($elementsStack) ? $elementsStack : $this->elements;
        foreach ($loop as $node) {
            if ($node->isSameNode($nodeToCheck)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Enter description here...
     *
     * @return phpQueryObject|QueryTemplatesSource|QueryTemplatesParse|QueryTemplatesSourceQuery
     */
    public function parent($selector = null)
    {
        $stack = array();
        foreach ($this->elements as $node) {
            if ($node->parentNode && !$this->elementsContainsNode($node->parentNode, $stack)) {
                $stack[] = $node->parentNode;
            }
        }
        $this->elementsBackup = $this->elements;
        $this->elements = $stack;
        if ($selector) {
            $this->filter($selector, true);
        }

        return $this->newInstance();
    }

    /**
     * Enter description here...
     *
     * @return phpQueryObject|QueryTemplatesSource|QueryTemplatesParse|QueryTemplatesSourceQuery
     */
    public function parents($selector = null)
    {
        $stack = array();
        if (!$this->elements) {
            $this->debug('parents() - stack empty');
        }
        foreach ($this->elements as $node) {
            $test = $node;
            while ($test->parentNode) {
                $test = $test->parentNode;
                if ($this->isRoot($test)) {
                    break;
                }
                if (!$this->elementsContainsNode($test, $stack)) {
                    $stack[] = $test;
                    continue;
                }
            }
        }
        $this->elementsBackup = $this->elements;
        $this->elements = $stack;
        if ($selector) {
            $this->filter($selector, true);
        }

        return $this->newInstance();
    }

    /**
     * Internal stack iterator.
     */
    public function stack($nodeTypes = null)
    {
        if (!isset($nodeTypes)) {
            return $this->elements;
        }
        if (!is_array($nodeTypes)) {
            $nodeTypes = array($nodeTypes);
        }
        $return = array();
        foreach ($this->elements as $node) {
            if (in_array($node->nodeType, $nodeTypes)) {
                $return[] = $node;
            }
        }

        return $return;
    }

    // TODO phpdoc; $oldAttr is result of hasAttribute, before any changes
    protected function attrEvents($attr, $oldAttr, $oldValue, $node)
    {
        // skip events for XML documents
        if (!$this->isXHTML() && !$this->isHTML()) {
            return;
        }
        $event = null;
        // identify
        $isInputValue = $node->tagName == 'input'
                && (
                in_array($node->getAttribute('type'), array('text', 'password', 'hidden'))
                || !$node->getAttribute('type')
                );
        $isRadio = $node->tagName == 'input'
                && $node->getAttribute('type') == 'radio';
        $isCheckbox = $node->tagName == 'input'
                && $node->getAttribute('type') == 'checkbox';
        $isOption = $node->tagName == 'option';
        if ($isInputValue && $attr == 'value' && $oldValue != $node->getAttribute($attr)) {
            $event = new DOMEvent(array(
                        'target' => $node,
                        'type' => 'change',
                    ));
        } elseif (($isRadio || $isCheckbox) && $attr == 'checked' && (
                // check
                (!$oldAttr && $node->hasAttribute($attr))
                // un-check
                || (!$node->hasAttribute($attr) && $oldAttr)
                )) {
            $event = new DOMEvent(array(
                        'target' => $node,
                        'type' => 'change',
                    ));
        } elseif ($isOption && $node->parentNode && $attr == 'selected' && (
                // select
                (!$oldAttr && $node->hasAttribute($attr))
                // un-select
                || (!$node->hasAttribute($attr) && $oldAttr)
                )) {
            $event = new DOMEvent(array(
                        'target' => $node->parentNode,
                        'type' => 'change',
                    ));
        }
        if ($event) {
            phpQueryEvents::trigger($this->getDocumentID(), $event->type, array($event), $node
            );
        }
    }

    public function attr($attr = null, $value = null)
    {
        foreach ($this->stack(1) as $node) {
            if (!is_null($value)) {
                $loop = $attr == '*' ? $this->getNodeAttrs($node) : array($attr);
                foreach ($loop as $a) {
                    $oldValue = $node->getAttribute($a);
                    $oldAttr = $node->hasAttribute($a);
                    // TODO raises an error when charset other than UTF-8
                    // while document's charset is also not UTF-8
                    @$node->setAttribute($a, $value);
                    $this->attrEvents($a, $oldAttr, $oldValue, $node);
                }
            } elseif ($attr == '*') {
                // jQuery difference
                $return = array();
                foreach ($node->attributes as $n => $v) {
                    $return[$n] = $v->value;
                }

                return $return;
            } else {
                return $node->hasAttribute($attr) ? $node->getAttribute($attr) : null;
            }
        }

        return is_null($value) ? '' : $this;
    }

    /**
     */
    protected function getNodeAttrs($node)
    {
        $return = array();
        foreach ($node->attributes as $n => $o) {
            $return[] = $n;
        }

        return $return;
    }

