    if (isset($_POST['action']) && $_POST['action'] == 'SubpanelCreates') {
        $actual_module = $_POST['target_module'];
        if (!empty($GLOBALS['modListHeader']) && !in_array($actual_module, $GLOBALS['modListHeader'])) {
            $this->controller->hasAccess = false;
        }
